begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1717 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5249e4cec98afdcbade660b8' and md5(to_jsonb(t)::text)='0c2c2a8b99bf5e0792bc5fdc728ecc07')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5249e4cec98afdcbade660b8';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_97c32ceb21545f0e$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta baraja, que normalmente se encuentra dentro de una caja o bolsa, contiene cartas hechas de marfil o vitela. La mayoría (75 %) de estas barajas disponen solo de trece cartas, pero el resto tienen veintidós.\n\nAntes de robar una carta, debes declarar cuántas pretendes robar y, a continuación, robarlas al azar (puedes utilizar una baraja de naipes alterada para simular esta baraja). Cualquier carta robada por encima de la cantidad declarada no tiene efecto. Por lo demás, en cuanto robes una carta de la baraja, su magia producirá el efecto que corresponda. Debes robar cada carta antes de que pase 1 hora desde el robo anterior. Si no robas la cantidad de cartas declaradas, las cartas restantes saldrán volando de la baraja por su cuenta y tendrán efecto a la vez.\n\nCuando robas una carta, desaparece de tu mano. A menos que sea el Loco o el Bufón, la carta volverá a la baraja, por lo que será posible robarla dos veces.\n\nAs de diamantes · Visir*\nRey de diamantes · Sol\nReina de diamantes · Luna\nJota de diamantes · Estrella\nDos de diamantes · Cometa*\nAs de corazones · Los Hados*\nRey de corazones · Trono\nReina de corazones · Llave\nJota de corazones · Caballero\nDos de corazones · Gema*\nAs de tréboles · Garras*\nRey de tréboles · El Vacío\nReina de tréboles · Llamas\nJota de tréboles · Calavera\nDos de tréboles · Idiota*\nAs de picas · Calabozo*\nRey de picas · Ruina\nReina de picas · Euríale\nJota de picas · Canalla\nDos de picas · Equilibrio*\nComodín (rojo) · Loco*\nComodín (negro) · Bufón\n\n*Solo se encuentra en una baraja de veintidós cartas.\n\nBufón. Ganas 10 000 PX o puedes robar dos cartas más de las que declaraste.\n\nCaballero. Un personaje no jugador de la clase guerrero de nivel 4 se pone a tu servicio. Aparecerá en un espacio de tu elección a 9 m o menos de ti. Es de tu misma raza y te servirá con lealtad hasta la muerte, ya que cree que el destino le ha llevado junto a ti. Controlas a este personaje.\n\nCalabozo. Desapareces y quedas sepultado en un estado de animación suspendida en una esfera extradimensional. Todo lo que llevaras y vistieras se queda donde estabas, en el espacio que ocupabas cuando desapareciste. Permanecerás encarcelado hasta que te encuentren y te saquen de la esfera. No se te puede localizar mediante magia de adivinación, pero sí mediante un conjuro deseo. No robas más cartas.\n\nCalavera. Invocas a un avatar de la muerte: un esqueleto de humanoide fantasmal vestido con una raída túnica negra y que empuña una guadaña espectral. Aparece en un espacio a 3 m o menos de ti a elección de tu GM y te ataca, a la par que advierte al resto que debes derrotarlo en solitario. El avatar luchará contra ti hasta que mueras o hasta que sus puntos de golpe se reduzcan a 0, momento en que desaparecerá. Si alguien intenta ayudarte, el ayudante invocará a su propio avatar de la muerte. Cualquier criatura que sucumba ante un avatar de la muerte no puede revivir. Avatar de la muerte Muerto viviente Mediano, neutral malvado Clase de Armadura: 20 Puntos de golpe: la mitad del máximo de su invocador Velocidad: 18 m, volar 18 m (levitar) FUE DES CON INT SAB CAR\n\n16 (+3) 16 (+3) 16 (+3) 16 (+3) 16 (+3) 16 (+3) Inmunidad a daño: necrótico, veneno Inmunidad a estados: asustado, envenenado, hechizado, inconsciente, paralizado, petrificado Sentidos: visión en la oscuridad 18 m, visión verdadera 18 m, Percepción pasiva 13 Idiomas: todos los que conozca su invocador Desafío: — (0 PX) Inmunidad a Expulsión. El avatar es inmune a los efectos que expulsan muertos vivientes. Movimiento Incorpóreo. El avatar puede moverse a través de otras criaturas y objetos como si fueran terreno difícil. Recibe 5 (1d10) de daño de fuerza si acaba su turno dentro de un objeto. Acciones Guadaña segadora. El avatar barre con su guadaña espectral a una criatura que esté a 1,5 m o menos de él y le inflige 7 (1d8 +3) de daño cortante más 4 (1d8) de daño necrótico.\n\nCanalla. Un personaje no jugador a elección de tu GM se vuelve hostil hacia ti. La identidad de tu nuevo enemigo será desconocida hasta que el PNJ u otro personaje la revelen. Salvo un conjuro deseo o la intercesión divina, nada puede hacer que esta hostilidad cese.\n\nCometa. Si derrotas sin ayuda al siguiente monstruo o grupo de monstruos hostiles que te encuentres, ganas suficientes puntos de experiencia para subir de nivel. De lo contrario, la carta no tiene efecto.\n\nEstrella. Aumenta en 2 una de tus puntuaciones de característica. Puede pasar de 20, pero no de 24.\n\nEquilibrio. Tu mente sufre una alteración terrible, lo que causa que tu alineamiento cambie. Legal se vuelve caótico, bueno se vuelve malvado y viceversa. Si eres neutral verdadero o sin alineamiento, esta carta no te afecta.\n\nEuríale. La cara de medusa de la carta te lanza una maldición. Recibes un penalizador de −2 a tus tiradas de salvación mientras estés bajo su influjo. Solo un dios o la magia de Los Hados pueden acabar con esta maldición.\n\nGarras. Todos los objetos mágicos que vistas o lleves contigo se desintegran. Los artefactos que poseas no se destruyen, pero desaparecen.\n\nGema. Aparecen a tus pies veinticinco joyas con un valor de 2000 po cada una o cincuenta gemas con un valor de 1000 po cada una.\n\nLos Hados. El tejido del universo se desteje y se teje de nuevo, lo que te permite evitar o borrar un suceso, como si nunca hubiera ocurrido. Puedes usar esta magia tan pronto como robes la carta o en cualquier momento antes de morir.\n\nIdiota. Tu Inteligencia se reduce permanente- mente en 1d4 + 1 (hasta un mínimo de 1). Puedes robar una carta más de las que declaraste.\n\nLlamas. Un poderoso diablo se convierte en tu enemigo. Buscará tu ruina y te acosará, además de regodearse con tu sufrimiento antes de intentar matarte. Esta enemistad dura hasta que el diablo o tú muráis.\n\nLlave. Aparece en tus manos un arma mágica rara o de mayor rareza con la que eres competente. Tu GM elige el arma.\n\nLoco. Pierdes 10 000 PX, descartas esta carta y robas otra vez de la baraja; ambos robos solo contarán como uno de tus robos declarados. Si esa pérdida de PX te haría bajar de nivel, en vez de eso, perderás la cantidad de PX justa para quedarte en tu nivel actual.\n\nLuna. Obtienes la capacidad de lanzar el conjuro deseo 1d3 veces.\n\nRuina. Pierdes todas las riquezas que lleves o poseas, excepto los objetos mágicos. Las propiedades que puedas llevar encima desaparecen. Pierdes todos los negocios, edificios y tierras que poseas de la manera que menos altere la realidad. Cualquier documento que pruebe que deberías poseer las riquezas perdidas por esta carta también desaparece.\n\nSol. Ganas 50 000 PX y en tus manos aparece un objeto maravilloso (tu GM lo determina al azar).\n\nTrono. Ganas competencia en la habilidad Persuasión y duplicas tu bonificador por competencia en las pruebas de esa habilidad. Además, obtienes de pleno derecho la propiedad de una pequeña fortaleza en alguna parte del mundo. No obstante, ahora mismo la habitan monstruos, a los que deberás expulsar antes de reclamar la fortaleza.\n\nEl Vacío. Esta carta negra vaticina una catástrofe. Tu alma se extrae de tu cuerpo y va a parar al interior de un objeto situado en un lugar a elección de tu GM. Uno o más seres poderosos custodian ese sitio. Mientras tu alma esté atrapada de este modo, tu cuerpo quedará incapacitado. Un conjuro deseo no puede traer de vuelta tu alma, pero sí revela la ubicación del objeto que la contiene. No robas más cartas.\n\nVisir. En cualquier momento que quieras hasta un año después de robar esta carta, podrás hacer una pregunta mientras meditas y recibirás mentalmente una respuesta veraz a dicha cuestión. Además de proporcionarte información, la respuesta te ayudará a resolver un problema u otro dilema. Dicho de otro modo, el conocimiento se obtiene junto con la sabiduría necesaria para aplicarlo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_97c32ceb21545f0e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5249e4cec98afdcbade660b8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:52afc9a130f0d37aed94ef12' and md5(to_jsonb(t)::text)='646f18310717a9f92c5b22f5813f110c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:52afc9a130f0d37aed94ef12';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_dd56e0a78c09c5ba$"Objeto · Precio base · Peso\nÚtiles de herborista · 5 po · 3 lb\n\nÚtiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_dd56e0a78c09c5ba$::jsonb,true),'{features}',$text_61e38f752e2d89de$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_61e38f752e2d89de$::jsonb,true),'{rules,definition,description}',$text_60ab5a3c8c12bf60$[{"id":"official-table","rows":[["Útiles de herborista","5 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Útiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_60ab5a3c8c12bf60$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:52afc9a130f0d37aed94ef12';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:52c0cef94e13699b0ea2c75d' and md5(to_jsonb(t)::text)='b4c7d5b27af4f4b68995e08a31693ec3')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:52c0cef94e13699b0ea2c75d';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_5226a28bfab9e8f8$[{"id":"official-base-table","rows":[["Hacha de mano","5 po","2 lb","1d6 cortante","+0","Ligera, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_5226a28bfab9e8f8$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_f30737b33e327572$["official-base-table","property-light","property-thrown","family-rule"]$text_f30737b33e327572$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:52c0cef94e13699b0ea2c75d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:536aff9fe0a2d11fe8d4ee85' and md5(to_jsonb(t)::text)='c6d8a2aac7d573ba72052310932076fd')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:536aff9fe0a2d11fe8d4ee85';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3d20682e3808f6a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para soplar este cuerno. Como respuesta, varios espíritus guerreros del Valhalla aparecerán a 18 m o menos de ti. Utilizan el perfil del berserker. Regresarán al Valhalla después de 1 hora o cuando sus puntos de golpe se reduzcan a 0. Una vez que utilices el cuerno, no podrás volver a usarlo hasta que hayan pasado 7 días.\n\nSe conoce la existencia de cuatro tipos de cuerno del Valhalla, cada uno hecho de un metal distinto. El tipo de cuerno determina cuántos berserkers responden a su llamada, así como el requisito para utilizarlo. Tu GM elige el tipo de cuerno o lo determina al azar.\n\n01–40 · Plata · 2d4 + 2 · Ninguno\n41–75 · Oropel · 3d4 + 3 · Competencia con todas las armas sencillas\n76–90 · Bronce · 4d4 + 4 · Competencia con todas las armaduras medias\n91–00 · Hierro · 5d4 + 5 · Competencia con todas las armas marciales\n\nSi soplas el cuerno sin cumplir su requisito, los berserkers invocados te atacarán. Si cumples el requisito, serán amistosos contigo y tus compañeros, y seguirán tus órdenes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3d20682e3808f6a0$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:536aff9fe0a2d11fe8d4ee85';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5390e688d545c3237cbd0c5c' and md5(to_jsonb(t)::text)='42cfbe988381761594cf2aab50fd3ffa')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5390e688d545c3237cbd0c5c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_9ee94858c2caa629$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +3 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador a la CA mientras lleves esta armadura. El bonificador depende de su rareza.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9ee94858c2caa629$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5390e688d545c3237cbd0c5c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:541bab9b71892325839d85c0' and md5(to_jsonb(t)::text)='fa12068022c3272d513796ba16b67f40')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:541bab9b71892325839d85c0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_78cacd5c998f65d7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo está vinculado a uno de los cuatro Planos Elementales. Tu GM elige el plano o lo determina al azar.\n\nMientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales del plano vinculado y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a ciertas propiedades en función del plano vinculado.\n\nEl anillo tiene 5 cargas. Recupera 1d4 +1 cargas empleadas cada día, al amanecer. Los conjuros lanzados desde el anillo tienen una CD de salvación de 17.\n\nAnillo de comandar elementales de agua. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de agua. Además, puedes permanecer de pie sobre superficies líquidas y andar por ellas como si fueran terreno firme. También puedes hablar y entender acuano.\n\nSi ayudas a matar a un elemental de agua mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Puedes respirar bajo el agua y obtienes una velocidad nadando igual a tu velocidad caminando. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: crear o destruir agua (1 carga), controlar agua (3 cargas), muro de hielo (3 cargas) o tormenta de hielo (2 cargas).\n\nAnillo de comandar elementales de aire. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de aire. Además, cuando caigas, descenderás 18 m por asalto y no sufrirás daño por la caída. También puedes hablar y entender aurano.\n\nSi ayudas a matar a un elemental de aire mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de relámpago. • Tienes una velocidad volando igual a tu velocidad caminando y puedes levitar. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: muro de viento (1 carga), ráfaga de viento (2 cargas) o relámpago en cadena (3 cargas).\n\nAnillo de comandar elementales de fuego. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de fuego. Además, tienes resistencia al daño de fuego. También puedes hablar y entender ígneo.\n\nSi ayudas a matar a un elemental de fuego mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Eres inmune al daño de fuego. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: bola de fuego (2 cargas), manos ardientes (1 carga) o muro de fuego (3 cargas).\n\nAnillo de comandar elementales de tierra. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de tierra. Además, puedes moverte por terreno difícil compuesto de escombros, rocas o tierra como si fuera terreno normal. También puedes hablar y entender terrano.\n\nSi ayudas a matar a un elemental de tierra mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de ácido. • Puedes moverte a través de tierra sólida o roca como si estas superficies fueran terreno difícil. Si acabas tu turno en ellas, irás a parar al espacio sin ocupar más cercano en el que estuviste por última vez. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: moldear la piedra (2 cargas), muro de piedra (3 cargas) o piel pétrea (3 cargas).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_78cacd5c998f65d7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:541bab9b71892325839d85c0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:54bd24ef297c7d88cdcc3f10' and md5(to_jsonb(t)::text)='59c8ead9e8e848f29b48d66ce2ada415')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:54bd24ef297c7d88cdcc3f10';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8d172254ea0ad766$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este frasco con tapón suena cuando se agita, como si tuviera agua dentro. Pesa 1 kg.\n\nPuedes utilizar una acción para retirar el tapón y pronunciar una de las tres palabras de activación. A continuación, cierta cantidad de agua dulce o salada (a tu elección) saldrá del frasco. El agua dejará de salir al principio de tu siguiente turno. Elige una de las siguientes opciones: • “Arroyo” produce 4 l de agua. • “Fuente” produce 20 l de agua. • “Géiser” produce 120 l de agua que salen disparados en un géiser de 9 m de largo y 30 cm de ancho. Como acción adicional mientras sostienes el decantador, puedes apuntar con el géiser a una criatura que puedas ver a 9 m o menos de ti. El objetivo deberá superar una tirada de salvación de Fuerza con CD 13 o sufrirá 1d4 de daño contundente y será derribado. En vez de una criatura, puedes apuntar a un objeto que no lleve ni vista nadie y que no pese más de 100 kg. Este objeto se volcará o será empujado hasta 4,5 m en dirección contraria a ti.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8d172254ea0ad766$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:54bd24ef297c7d88cdcc3f10';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:551cabb8577067cfc1e49fb9' and md5(to_jsonb(t)::text)='3600c1a82a6755729c470aef064274fe')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:551cabb8577067cfc1e49fb9';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8f91ebf32c6041b7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica. Cuando impactes a un infernal o muerto viviente con ella, esa criatura recibirá 2d10 de daño radiante adicional.\n\nMientras empuñes la espada desenvainada, creará un aura de 3 m de radio alrededor de ti. Tú y todas las criaturas amistosas contigo dentro del aura tendréis ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos. Si tienes 17 o más niveles en la clase paladín, el radio del aura aumentará en 9 m.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8f91ebf32c6041b7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:551cabb8577067cfc1e49fb9';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:563d29e14ec46eb9bf800072' and md5(to_jsonb(t)::text)='62bbbe2908fa4d1bb8196bb3ea76a968')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:563d29e14ec46eb9bf800072';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_03936579a7d7f959$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás permanecer de pie sobre cualquier superficie líquida y desplazarte por ella como si fuera terreno firme.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_03936579a7d7f959$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:563d29e14ec46eb9bf800072';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:57bf7eb989a1861f3147626f' and md5(to_jsonb(t)::text)='b12ca382e943ecf64364f358f8ffc8a4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:57bf7eb989a1861f3147626f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_e015e324b8e97263$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar el conjuro relámpago (CD de salvación 15) desde ella. Si empleas 1 carga, podrás lanzar la versión de nivel 3 del conjuro. Puedes aumentar el nivel del espacio de conjuro en 1 por cada carga adicional que emplees.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e015e324b8e97263$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:57bf7eb989a1861f3147626f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:58484f3b7d519324fe81e80c' and md5(to_jsonb(t)::text)='9c42f699abd2974c0a3a75193498fb55')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:58484f3b7d519324fe81e80c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f0e511db536bffb9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Los puntos de golpe perdidos por el daño de esta arma solo pueden recuperarse mediante un descanso corto o largo, no mediante la regeneración, la magia o cualquier otro medio.\n\nUna vez por turno, cuando impactes a una criatura con un ataque usando esta arma mágica, podrás herirla. Al principio de cada turno de la criatura herida, sufrirá 1d4 de daño necrótico por cada vez que la hayas herido y luego podrá realizar una tirada de salvación de Constitución con CD 15 para acabar con el efecto de esas heridas si la supera. Como alternativa, la criatura herida u otra que se encuentre a 1,5 m o menos de ella podrá usar una acción para realizar una prueba de Sabiduría (Medicina) con CD 15 y acabar con el efecto de las heridas si la supera.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f0e511db536bffb9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:58484f3b7d519324fe81e80c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:594081d8f38c71118bc60395' and md5(to_jsonb(t)::text)='a59667b316efebb3c58f5c6f71659661')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:594081d8f38c71118bc60395';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_d53dd2492eead013$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, podrás lanzar a voluntad el conjuro encantar animal (CD de salvación 13) durante 1 hora. Si agitas este líquido turbio, verás pequeños fragmentos: una escama de un pez, la lengua de un colibrí, la garra de un gato o el pelo de una ardilla.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_d53dd2492eead013$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:594081d8f38c71118bc60395';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5a6e10a599f12e551f1d8566' and md5(to_jsonb(t)::text)='c623ae95e05f5e452f8d78f3ffcddad7')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5a6e10a599f12e551f1d8566';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_febf6dfd9bd447b7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa, proyectará una ilusión que hace que parezcas estar en un lugar cerca de tu ubicación real, lo que provoca que todas las criaturas tengan desventaja en las tiradas de ataque contra ti. Si recibes daño, la propiedad dejará de funcionar hasta el principio de tu siguiente turno. Esta propiedad quedará suprimida mientras estés apresado, incapacitado o no puedas moverte por algún motivo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_febf6dfd9bd447b7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5a6e10a599f12e551f1d8566';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5af2e272b32cb89586b0a2d9' and md5(to_jsonb(t)::text)='11693ff49f980dbd3c060371927f72eb')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5af2e272b32cb89586b0a2d9';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f6ec61ea920b1c34$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia al daño no mágico mientras lleves esta armadura. Además, puedes utilizar una acción para hacerte inmune al daño no mágico durante 10 minutos o hasta que te quites la armadura. Una vez utilizada, esta acción especial no puede volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f6ec61ea920b1c34$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5af2e272b32cb89586b0a2d9';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5af4e6bb6390ffae681ef6a5' and md5(to_jsonb(t)::text)='217eee439aad51a93aa38b2708012772')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5af4e6bb6390ffae681ef6a5';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7bac77febfece550$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estos guantes parecen fundirse con tus manos cuando te los pones. Cuando un ataque con arma a distancia te impacte mientras los lleves puestos, podrás usar tu reacción para reducir el daño en 1d10 + tu modificador por Destreza, siempre y cuando tengas una mano libre. Si reduces el daño a 0, podrás atrapar el proyectil si es lo bastante pequeño como para sujetarlo con esa mano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7bac77febfece550$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5af4e6bb6390ffae681ef6a5';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5b1a504148920a35312b923e' and md5(to_jsonb(t)::text)='c774294d2264415a129350320684c44d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5b1a504148920a35312b923e';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_e2c5a5ebcb34ab5f$[{"id":"official-base-table","rows":[["Pica","5 po","18 lb","1d10 perforante","+0","Pesada, Gran alcance, A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-heavy","text":"Pesada. Las criaturas Pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. Su tamaño y peso hacen que sean demasiado voluminosas para que una criatura Pequeña las use con efectividad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_e2c5a5ebcb34ab5f$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_84a25ae6b543e731$["official-base-table","property-heavy","property-reach","property-two-handed","family-rule"]$text_84a25ae6b543e731$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:5b1a504148920a35312b923e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5b5c9f4db3a6a9bf121717fe' and md5(to_jsonb(t)::text)='2df62e7a723365309f085c15bc70c5bd')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5b5c9f4db3a6a9bf121717fe';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_1c3c594fc8815384$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delicada tela negra, suave como la seda, está doblada para tener las dimensiones de un pañuelo. Al desdoblarla, se convierte en una sábana circular de 1,8 m de diámetro.\n\nPuedes utilizar una acción para desdoblar y colocar el pozo de los muchos mundos sobre una superficie sólida, en la que creará un portal a otro mundo o plano de existencia que funciona en ambos sentidos. Cada vez que el objeto abra un portal, tu GM decidirá adónde conduce. Puedes utilizar una acción para cerrar un portal abierto sujetando los bordes de la tela y doblándola. En cuanto el pozo de los muchos mundos haya abierto un portal, no podrá volver a hacerlo durante 1d8 horas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_1c3c594fc8815384$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5b5c9f4db3a6a9bf121717fe';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5c10f65193e2bb033dd88f9e' and md5(to_jsonb(t)::text)='005eb3f3529454a96a2b659b74f8c2fb')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5c10f65193e2bb033dd88f9e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_cc0b7d4845f016f9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este objeto parece una empuñadura de espada larga. Mientras la agarras, puedes usar una acción adicio- nal para hacer que brote o desaparezca de ella una hoja de puro resplandor. Mientras la hoja exista, esta espada larga mágica tiene la propiedad “sutil”. Si eres competente con espadas cortas o largas, serás competente con la espada solar.\n\nRecibes un bonificador de +2 a las tiradas de ataque y de daño realizadas con esta arma, que causa daño radiante en vez de daño cortante. Cuando impactes a un muerto viviente con ella, el objetivo recibirá 1d8 de daño radiante adicional.\n\nLa hoja luminosa de la espada emite luz brillante en un radio de 4,5 m y luz tenue 4,5 m más allá. Esta luz es luz solar. Mientras esté la hoja, podrás usar una acción para ampliar o reducir el radio de la luz brillante y tenue en 1,5 m respectivamente, hasta un máximo de 9 m o un mínimo de 3 m cada una.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_cc0b7d4845f016f9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5c10f65193e2bb033dd88f9e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5e7858f630e21b5d417a1498' and md5(to_jsonb(t)::text)='4ca97afa03fc8e975bede1aca7e7c0e8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5e7858f630e21b5d417a1498';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ade9bf6dba635437$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para pronunciar la palabra de activación del cuerno y después soplarlo, lo que emitirá un estallido estruendoso en un cono de 9 m que se puede oír a 180 m de distancia. Todas las criaturas situadas en el cono deberán hacer una tirada de salvación de Constitución con CD 15. Si la fallan, recibirán 5d6 de daño de trueno y quedarán ensordecidas durante 1 minuto. Si la superan, recibirán la mitad de ese daño y no quedarán ensordecidas. Los objetos y criaturas de cristal o vidrio tendrán desventaja en la tirada de salvación y sufrirán 10d6 de daño de trueno en vez de 5d6.\n\nCada uso de la magia del cuerno tiene un 20 % de probabilidad de hacerlo explotar. La explosión inflige 10d6 de daño de fuego a quien lo haya soplado y destruirá el cuerno.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ade9bf6dba635437$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5e7858f630e21b5d417a1498';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5ee19ca247f4fd7289aab395' and md5(to_jsonb(t)::text)='695f6b8213d8a8993319b7b0cb022416')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5ee19ca247f4fd7289aab395';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_216b4d63fe402084$"Objeto · Precio base · Peso\nPitón · 5 pc · 0.25 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_216b4d63fe402084$::jsonb,true),'{rules,definition,description}',$text_70ac9ee2fca680b8$[{"id":"official-table","rows":[["Pitón","5 pc","0.25 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_70ac9ee2fca680b8$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:5ee19ca247f4fd7289aab395';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5f608ab32b300011f295ecc8' and md5(to_jsonb(t)::text)='d42008599ceba9b76a8465cd6a93e1e0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5f608ab32b300011f295ecc8';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_79c59cddc0e13072$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica. Tiene la propiedad “arrojadiza”, con un alcance normal de 6 m y un alcance largo de 18 m. Cuando impactas con un ataque a distancia con esta arma, inflige 1d8 de daño adicional o, si el objetivo es un gigante, 2d8. Justo después del ataque, el arma regresa volando a tu mano.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_79c59cddc0e13072$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5f608ab32b300011f295ecc8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5fcf7a51d08d0aecbe269fd4' and md5(to_jsonb(t)::text)='c6de8ea47521b48732c9c52ac14557bb')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5fcf7a51d08d0aecbe269fd4';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_33444504bb0c5fb3$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás utilizar una acción para pronunciar su palabra de activación e invocar a un determinado djinn del Plano Elemental del Aire. El djinn aparecerá en un espacio sin ocupar que elijas a 36 m o menos de ti. Permanecerá mientras te concentres (como si te concentraras en un conjuro) hasta un máximo de 1 hora o hasta que sus puntos de golpe se reduzcan a 0. A continuación, regresará a su plano.\n\nMientras esté invocado, el djinn será amistoso contigo y tus compañeros. Obedecerá cualquier orden que le des, utilices el idioma que utilices. Si no le das ninguna, el djinn se defenderá de los atacantes, pero no llevará a cabo ninguna otra acción.\n\nUna vez que se haya ido, no se podrá volver a invocarlo durante 24 horas. El anillo se volverá no mágico si el djinn muere.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_33444504bb0c5fb3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5fcf7a51d08d0aecbe269fd4';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:5ff00bfd7ee36f8d690360b2' and md5(to_jsonb(t)::text)='34508fadc9b1f5b4f542a9b352dd885e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:5ff00bfd7ee36f8d690360b2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_29a98243d423565f$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tomo contiene la información y los ensalmos necesarios para crear un tipo concreto de gólem. Tu GM elige el tipo o lo determina al azar. Para descifrar y usar el manual, debes ser un lanzador de conjuros con al menos dos espacios de conjuro de nivel 5. Si una criatura no puede usar un manual de gólems y trate de leerlo, sufrirá 6d6 de daño psíquico.\n\n1–5 · Arcilla · 30 días · 65 000 po\n6–17 · Carne · 60 días · 50 000 po\n18 · Hierro · 120 días · 100 000 po\n19–20 · Piedra · 90 días · 80 000 po\n\nPara crear un gólem, debes dedicar el tiempo mostrado en la tabla, trabajar sin interrupciones con el manual a mano y no descansar durante más de 8 horas al día. También debes pagar el precio especificado para comprar los suministros.\n\nEn cuanto hayas acabado de crear al gólem, el libro arderá en llamas sobrenaturales. El gólem cobrará vida cuando se esparzan sobre él las cenizas del manual. Estará bajo tu control, entenderá tus órdenes verbales y las obedecerá.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_29a98243d423565f$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:5ff00bfd7ee36f8d690360b2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:603a7612a52f1b0dc500319a' and md5(to_jsonb(t)::text)='72af23a1f5ec48941e50c7f8ce6c6dd8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:603a7612a52f1b0dc500319a';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7abd4351a086fcc3$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás una velocidad trepando igual a tu velocidad caminando durante 1 hora. Durante ese tiempo, tendrás ventaja en las pruebas de Fuerza (Atletismo) que hagas para trepar. La poción se separa en tres capas (marrón, plateada y gris) que parecen los estratos de una roca. Si agitas la botella, los colores no se mezclan.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_7abd4351a086fcc3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:603a7612a52f1b0dc500319a';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:607b667eddf76a4b1dda4c2e' and md5(to_jsonb(t)::text)='22fa17ae19ba99aca6c72ea013d272fa')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:607b667eddf76a4b1dda4c2e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_fa61d6dec4567eb9$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"En el exterior de este recipiente se forman gotitas de un aceite turbio y gris que se evaporan rápidamente. El aceite puede cubrir a una criatura Mediana o más pequeña, así como el equipo que vista o lleve. Se necesita un vial extra por cada categoría de tamaño por encima de Mediano. Aplicar el aceite lleva 10 minutos. La criatura afectada obtiene el efecto del conjuro excursión etérea durante 1 hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_fa61d6dec4567eb9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:607b667eddf76a4b1dda4c2e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:61f89fe62d631f3cdc73f2bc' and md5(to_jsonb(t)::text)='f4ed9d3f2bea3a95e7b44821f00c4595')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:61f89fe62d631f3cdc73f2bc';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_e0f585482b8941ad$"Objeto · Precio base · Peso\nÚtiles de escalada · 25 po · 12 lb\n\nÚtiles de escalada. Entre estos útiles se incluyen pitones especiales, puntas para las botas y un arnés. Puedes usar una acción para anclarte mediante estos útiles. Cuando lo hayas hecho, no podrás caer más de 7,5 m desde el punto en el que te ancles y no podrás subir más de 7,5 m de ese punto sin desanclarte.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_e0f585482b8941ad$::jsonb,true),'{features}',$text_f4c3ee5927eb8438$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles de escalada. Entre estos útiles se incluyen pitones especiales, puntas para las botas y un arnés. Puedes usar una acción para anclarte mediante estos útiles. Cuando lo hayas hecho, no podrás caer más de 7,5 m desde el punto en el que te ancles y no podrás subir más de 7,5 m de ese punto sin desanclarte.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_f4c3ee5927eb8438$::jsonb,true),'{rules,definition,description}',$text_3add5ea142dca2e1$[{"id":"official-table","rows":[["Útiles de escalada","25 po","12 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Útiles de escalada. Entre estos útiles se incluyen pitones especiales, puntas para las botas y un arnés. Puedes usar una acción para anclarte mediante estos útiles. Cuando lo hayas hecho, no podrás caer más de 7,5 m desde el punto en el que te ancles y no podrás subir más de 7,5 m de ese punto sin desanclarte.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_3add5ea142dca2e1$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:61f89fe62d631f3cdc73f2bc';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:63387bbd35bbb15be6d09c3e' and md5(to_jsonb(t)::text)='c8d48daf182f197c3b7c5c17e5b89d45')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:63387bbd35bbb15be6d09c3e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_e039cc2b5977900b$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este polvo, que se encuentra en paquetes pequeños, se asemeja a arena muy fina. Hay suficiente para un solo uso. Cuando empleas una acción para esparcir el polvo por el aire, tú y cada criatura y objeto que se esté a 3 m o menos de ti os volvéis invisibles durante 2d4 minutos. La duración es la misma para todos los afectados y el polvo se consume cuando la magia tiene efecto. Si una criatura afectada por el polvo ataca o lanza un conjuro, dejará de ser invisible.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_e039cc2b5977900b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:63387bbd35bbb15be6d09c3e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:656acc5366e5b282988b132f' and md5(to_jsonb(t)::text)='9c1e75282f45305f105f7e5f8236c62c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:656acc5366e5b282988b132f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8bd213ea78ae1ebe$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"De este collar cuelgan 1d6 + 3 cuentas. Puedes usar una acción para tirar una de estas cuentas a un punto a 18 m o menos de distancia. Cuando llegue al final de su trayectoria, la cuenta explotará como si fuera un conjuro bola de fuego de nivel 3 (CD de salvación 15).\n\nPuedes arrojar varias cuentas o incluso todo el collar en una acción. Si lo haces, aumenta el nivel de la bola de fuego en 1 por cada cuenta lanzada tras la primera.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8bd213ea78ae1ebe$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:656acc5366e5b282988b132f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:65b77c0aa953b874822fa87d' and md5(to_jsonb(t)::text)='97bf1f260fa62018d783b99f45ff25f8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:65b77c0aa953b874822fa87d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_833b89a0b7bc1930$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras este cuenco esté lleno de agua, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de agua, como si hubieras lanzado conjurar elemental. El cuenco no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEl cuenco tiene aproximadamente 30 cm de diámetro y la mitad de profundidad. Pesa 1,5 kg y puede contener unos 12 l.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_833b89a0b7bc1930$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:65b77c0aa953b874822fa87d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:669dbf2489ed293bb38d8a17' and md5(to_jsonb(t)::text)='4c0889717efa7fc33dd5aab7a6539466')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:669dbf2489ed293bb38d8a17';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_77d5fd2152d45fa4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene ejercicios de coordinación y equilibrio, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Destreza aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_77d5fd2152d45fa4$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:669dbf2489ed293bb38d8a17';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:670193d18fadb992218eedf7' and md5(to_jsonb(t)::text)='6a104a42c374f48fe8f6bb44ac26d9d3')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:670193d18fadb992218eedf7';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_22cd2279e0ae6955$[{"id":"official-base-table","rows":[["Martillo de guerra","15 po","2 lb","1d8 contundente","+0","Versátil","1d10"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_22cd2279e0ae6955$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_5488757723349d23$["official-base-table","property-versatile","family-rule"]$text_5488757723349d23$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:670193d18fadb992218eedf7';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6717fd92ac73e3765596e309' and md5(to_jsonb(t)::text)='6b0e63b72d130ffa55e14b36834c6963')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6717fd92ac73e3765596e309';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f7f023db0ab2a01d$"Objeto · Precio base · Peso\nAljaba · 1 po · 1 lb\n\nAljaba. Una aljaba puede contener hasta 20 flechas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f7f023db0ab2a01d$::jsonb,true),'{features}',$text_ad95de5033aa8476$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Aljaba. Una aljaba puede contener hasta 20 flechas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_ad95de5033aa8476$::jsonb,true),'{rules,definition,description}',$text_2553e910a16c7cd4$[{"id":"official-table","rows":[["Aljaba","1 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Aljaba. Una aljaba puede contener hasta 20 flechas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_2553e910a16c7cd4$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:6717fd92ac73e3765596e309';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:67c4d58203382e9febe67247' and md5(to_jsonb(t)::text)='a6dd4a9b637052b7e73693486920c3d0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:67c4d58203382e9febe67247';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3e0d16b332934568$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes este bastón, tendrás resistencia al daño de frío.\n\nEl bastón tiene 10 cargas. Mientras lo empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: cono de frío (5 cargas), muro de hielo (4 cargas), nube de oscurecimiento (1 carga) o tormenta de hielo (4 cargas).\n\nEl bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en agua y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3e0d16b332934568$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:67c4d58203382e9febe67247';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6807f943647e5f66904aab8c' and md5(to_jsonb(t)::text)='1e4ca61e6e2ba4ab0a5b0e128a6fbeea')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6807f943647e5f66904aab8c';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_c94309a253cab68c$[{"id":"official-base-table","rows":[["Cimitarra","25 po","3 lb","1d6 cortante","+0","Sutil, Ligera"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_c94309a253cab68c$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_144956692b2e784a$["official-base-table","property-finesse","property-light","family-rule"]$text_144956692b2e784a$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:6807f943647e5f66904aab8c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6880ccd9a4ad0a0ca9f7b45b' and md5(to_jsonb(t)::text)='537e1eef6975fbf4fabbdde6c2013bca')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6880ccd9a4ad0a0ca9f7b45b';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_040b04c1d262cc65$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"legacy-bonus-1","kind":"passive","name":"All","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las pruebas de habilidad.","showInActions":false},{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta ágata pulida contigo, recibirás un bonificador de +1 a las pruebas de característica y las tiradas de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":3,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta ágata pulida contigo, recibirás un bonificador de +1 a las pruebas de característica y las tiradas de salvación.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_040b04c1d262cc65$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6880ccd9a4ad0a0ca9f7b45b';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:68d0af6495ab84438d9efff3' and md5(to_jsonb(t)::text)='ef4925c7a08db22719824093b2e3cce4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:68d0af6495ab84438d9efff3';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_938576b2bfb086c3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para pronunciar la palabra de activación de este bastón y lanzarlo al suelo, a 3 m o menos de ti. El bastón se convertirá en una serpiente constrictora gigante bajo tu control y actuará en su propia posición en el orden de iniciativa. Si utilizas una acción adicional para pronunciar de nuevo la palabra de activación, el bastón recuperará su forma normal en un espacio que antes ocupaba la serpiente.\n\nEn tu turno, puedes dar órdenes mentales a la serpiente si se encuentra a 18 m o menos de ti y no estás incapacitado. Tú decides la acción que llevará a cabo la serpiente y adónde se desplazará durante su siguiente turno, o puedes darle una orden general, como atacar a tus enemigos o proteger un lugar.\n\nSi los puntos de golpe de la serpiente se reducen a 0, morirá y recuperará su forma de bastón. En tal caso, el bastón se hará añicos y se destruirá. Si la serpiente recupera la forma de bastón antes de perder todos sus puntos de golpe, los recuperará todos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_938576b2bfb086c3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:68d0af6495ab84438d9efff3';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:69d561ca2c3a56764e71cebd' and md5(to_jsonb(t)::text)='e1df130af12174cafec1b028fd731ff5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:69d561ca2c3a56764e71cebd';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b21f96047a351c1b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene consejos de salud y alimentación, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Constitución aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b21f96047a351c1b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:69d561ca2c3a56764e71cebd';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6b4e8a7ee89714ac92465871' and md5(to_jsonb(t)::text)='b82dadc8cfab9fbf7935c3f07a7fd772')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6b4e8a7ee89714ac92465871';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5479001584507f1e$"Objeto · Precio base · Peso\nReloj de arena · 25 po · 1 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5479001584507f1e$::jsonb,true),'{rules,definition,description}',$text_6188d493dbf01d15$[{"id":"official-table","rows":[["Reloj de arena","25 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_6188d493dbf01d15$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:6b4e8a7ee89714ac92465871';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6bcfc9fa2fc699815dbbb59f' and md5(to_jsonb(t)::text)='a2f7b5b01f8ded9f276c146306117726')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6bcfc9fa2fc699815dbbb59f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5efa713461f5b120$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6bcfc9fa2fc699815dbbb59f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6be205ff80da3f50db3b8036' and md5(to_jsonb(t)::text)='725d9a75896098c19fd5e04110bef926')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6be205ff80da3f50db3b8036';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5efa713461f5b120$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6be205ff80da3f50db3b8036';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6c18c45b014bd495b9788c25' and md5(to_jsonb(t)::text)='d44e6e60738bf8e5c9fbd10db7b56a00')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6c18c45b014bd495b9788c25';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6c18c45b014bd495b9788c25';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6c22746b8f06e620d1547a10' and md5(to_jsonb(t)::text)='86d4e92dd6729a4b8cb60f5e9c1784d5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6c22746b8f06e620d1547a10';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_700cde83ebc64f9c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nAbsorción (muy rara). Mientras este elipsoide de color lila claro gire alrededor de tu cabeza, podrás usar tu reacción para cancelar un conjuro de nivel 4 o inferior lanzado por una criatura que puedas ver y que solo te haga objetivo a ti.\n\nEn cuanto la piedra haya cancelado 20 niveles de conjuros, se volverá gris porque su magia se habrá agotado. Si eres el objetivo de un conjuro cuyo nivel sea superior a la cantidad de niveles de conjuro que le queden a la piedra, no podrá cancelarlo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_700cde83ebc64f9c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6c22746b8f06e620d1547a10';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6d0fa52287609369216948bf' and md5(to_jsonb(t)::text)='13c8e13dc5d322a902e74d4310a13597')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6d0fa52287609369216948bf';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ffeec24cc9187eb8$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un dragón con esta arma, este sufrirá 3d6 de daño adicional del tipo del arma. En lo que concierne a esta arma, “dragón” se refiere a cualquier criatura con el tipo “dragón”, incluidos seres como dragones tortuga y guivernos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ffeec24cc9187eb8$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6d0fa52287609369216948bf';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6d448708b838897d955a51eb' and md5(to_jsonb(t)::text)='0cd45de8e12206ba3d3cf14bd370b06d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6d448708b838897d955a51eb';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_025ea068512228e9$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica · Alcance normal/largo (pies)\nArco largo feroz · 50 po (solo objeto mundano base; no es el precio de la variante mágica) · 2 lb · 1d8 perforante · Munición, Pesada, A dos manos · +0 · 150/600\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_025ea068512228e9$::jsonb,true),'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_4bfc512a49fef2e9$[{"id":"official-table","rows":[["Arco largo feroz","50 po (solo objeto mundano base; no es el precio de la variante mágica)","2 lb","1d8 perforante","Munición, Pesada, A dos manos","+0","150/600"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"vicious-2014","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_4bfc512a49fef2e9$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6851a11da4c0ecd0$["official-table","vicious-2014"]$text_6851a11da4c0ecd0$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:6d448708b838897d955a51eb';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6deba73e296507e887a4ed1f' and md5(to_jsonb(t)::text)='4262af8a19317a3f8fe513266610dacf')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6deba73e296507e887a4ed1f';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_055d6faab42f5c07$[{"id":"official-base-table","rows":[["Lucero del alba","15 po","4 lb","1d8 perforante","+0","—"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_055d6faab42f5c07$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6834d0d967473cf4$["official-base-table","family-rule"]$text_6834d0d967473cf4$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:6deba73e296507e887a4ed1f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6e0e16ea21a0f01542022994' and md5(to_jsonb(t)::text)='c10ea04bafb3e69caa855742216432a5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6e0e16ea21a0f01542022994';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4a21ac4510aa7924$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta escoba de madera, que pesa 1,5 kg, funcionará como una escoba normal hasta que te montes en ella y pronuncies su palabra de activación. Entonces, levitará y podrás utilizarla para volar por el cielo. Tiene una velocidad volando de 15 m. Puede transportar hasta 200 kg, pero su velocidad volando se reduce a 9 m si transporta más de 100 kg. La escoba deja de levitar cuando aterrizas.\n\nPuedes ordenarle que viaje por sí misma a un lugar que esté a 1,5 km o menos de ti si pronuncias la palabra de activación, nombras el lugar y conoces el sitio en cuestión. La escoba regresará junto a ti cuando pronuncies otra palabra de activación mientras se encuentre a 1,5 km o menos de ti.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a21ac4510aa7924$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6e0e16ea21a0f01542022994';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6e83c9fa1434c8e5af25720e' and md5(to_jsonb(t)::text)='7f2a7beadb96a4857541333298cf5ae6')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6e83c9fa1434c8e5af25720e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3eedc59bbdbb862b$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de artista (40 po). Incluye una mochila, un petate, 2 disfraces, 5 velas, raciones para 5 días, una cantimplora y útiles para disfrazarse.\n\nDuración: Según su uso..","showInActions":false}]$text_3eedc59bbdbb862b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6e83c9fa1434c8e5af25720e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6eaa83f8bf3b7833d32c8ec4' and md5(to_jsonb(t)::text)='bf857d261eab9122a786c93dcc77ce60')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6eaa83f8bf3b7833d32c8ec4';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_fd3b1146f47c2c14$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delgada candela está dedicada a una deidad y comparte su alineamiento. El alineamiento de la vela se puede percibir con el conjuro detectar el bien y el mal. Tu GM elige el dios y el alineamiento asociado o determina el alineamiento al azar.\n\n1–2 · Caótico malvado\n3–4 · Caótico neutral\n5–7 · Caótico bueno\n8–9 · Neutral malvado\n10–11 · Neutral\n12–13 · Neutral bueno\n14–15 · Legal malvado\n16–17 · Legal neutral\n18–20 · Legal bueno\n\nLa magia de la vela se activa al encenderla, lo que requiere una acción. Después de arder durante 4 horas, la vela se destruye. Puedes apagarla antes de que pase ese tiempo para seguir usándola después. Resta el tiempo que ha ardido del total, en intervalos de 1 minuto.\n\nMientras permanezca encendida, la vela emitirá luz tenue en un radio de 9 m. Todas las criaturas que estén dentro de ese radio y cuyo alineamiento coincida con el de la vela realizarán las tiradas de ataque, las tiradas de salvación y las pruebas de característica con ventaja. Además, un clérigo o druida dentro del radio de la luz y cuyo alinea- miento coincida con el de la vela podrá lanzar conjuros de nivel 1 que tenga preparados sin gastar espacios de conjuro. El efecto de estos conjuros será el mismo que si se hubieran lanzado con un espacio de conjuro de nivel 1.\n\nComo alternativa, la primera vez que enciendas la vela, podrás utilizarla para lanzar el conjuro portal. Hacer esto destruirá la vela.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_fd3b1146f47c2c14$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6eaa83f8bf3b7833d32c8ec4';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6f505d7deed241155c4e0b85' and md5(to_jsonb(t)::text)='c24e2aa08e86cc887b893cb4c54532d3')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6f505d7deed241155c4e0b85';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8c07d2b3b737b96f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene ejercicios de lógica y memoria, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Inteligencia aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8c07d2b3b737b96f$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6f505d7deed241155c4e0b85';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 13 as batch,49 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;